using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static class Cave202Extras{
 [Serializable]class Row{public string side,light;public float before,after;public bool exact;}
 [Serializable]class Report{public bool pass;public Row[] rows;public string scope;}
 public static void Run(){string root=Path.GetFullPath(Path.Combine(Application.dataPath,"..")),output=Path.Combine(root,"Evidence202");try{
  var report=JsonUtility.FromJson<Folder>(File.ReadAllText(Path.Combine(output,"checks.json")));string after=report.folder;var oldPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot 17/cnd001.prefab");var newPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(after+"/cnd001.prefab");
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);GraphicsSettings.defaultRenderPipeline=QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.black;RenderSettings.ambientIntensity=0;RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;Shader.SetGlobalVector("_TDPineWind",new Vector4(.8f,.6f,.7f,1.25f));
  var cam=new GameObject("offscreen").AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.fieldOfView=38;var light=new GameObject("point").AddComponent<Light>();light.type=LightType.Point;light.intensity=3;light.range=5;light.color=new Color(1,.7f,.4f);var sun=new GameObject("sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1;sun.transform.rotation=Quaternion.Euler(50,25,0);var rows=new List<Row>();
  foreach(string side in new[]{"front","back"})foreach(string kind in new[]{"point","day","off"}){light.enabled=kind=="point";sun.enabled=kind=="day";byte[][] png=new byte[2][];float[] mean=new float[2];for(int stage=0;stage<2;stage++){var o=(GameObject)PrefabUtility.InstantiatePrefab(stage==0?oldPrefab:newPrefab);var renderer=o.GetComponent<Renderer>();var target=renderer.bounds.center;cam.transform.position=target+new Vector3(.7f,1,side=="front"?-1.5f:1.5f);cam.transform.LookAt(target);light.transform.position=target+new Vector3(.6f,1.4f,side=="front"?-1f:1f);var im=Shared117Review.Image(cam,480,360);png[stage]=im.EncodeToPNG();mean[stage]=im.GetPixels().Average(c=>(c.r+c.g+c.b)/3);if(kind=="point")File.WriteAllBytes(Path.Combine(output,"leaf-wind-"+side+"-"+stage+".png"),png[stage]);UnityEngine.Object.DestroyImmediate(im);UnityEngine.Object.DestroyImmediate(o);}bool exact=png[0].SequenceEqual(png[1]);if(kind!="point"&&!exact)throw new Exception("wind no-local changed");if(kind=="point"&&mean[1]<=mean[0]+.0001f)throw new Exception("wind side not lit");rows.Add(new Row{side=side,light=kind,before=mean[0],after=mean[1],exact=exact});}
  File.WriteAllText(Path.Combine(output,"leaf-wind.json"),JsonUtility.ToJson(new Report{pass=true,rows=rows.ToArray(),scope="Formal old/new fern; front/back; same nonzero wind vector and time; main/off exact"},true));
  var load=typeof(Cave202Checks).GetMethod("Load",BindingFlags.Static|BindingFlags.NonPublic);foreach(string stage in new[]{"before","after"}){var pf=AssetDatabase.LoadAssetAtPath<GameObject>((stage=="before"?"Assets/MapSharedPropsGenerated/Pilot 17":after)+"/cnd020.prefab");var result=(Array)load.Invoke(null,new object[]{pf});File.WriteAllText(Path.Combine(output,"load-"+stage+".json"),"["+string.Join(",",result.Cast<object>().Select(x=>JsonUtility.ToJson(x)))+"]");}
  EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(output,"extras-error.txt"),e.ToString());EditorApplication.Exit(1);}}
 [Serializable]class Folder{public string folder;}
}
